body.script:
const src = "https://cdn.jsdelivr.net/gh/Camzzz-vrgt/Toby-Web/tobywebsinglefile.html";
fetch(src)
  .then(r => {
    if (!r.ok) throw new Error(`Failed to fetch (${r.status})`);
    return r.text();
  })
  .then(html => {
    document.open();
    document.write(html);
    document.close();
  })
  .catch(err => {
    document.body.innerHTML = `

Failed to load Toby Web

${err.message}
    `;
  });
